{
  "findings": [
    {
      "ref": "[D503]",
      "area": "age_gating",
      "claim": "A parent reports that children under 13 can use Roblox if a parent creates a linked account and enables parental controls.",
      "stance": "mitigation",
      "quote": "Users ages 5 and older may create an Account, but certain features for the Services must be enabled by a parent or legal guardian through our Parental Controls."
    },
    {
      "ref": "[D503]",
      "area": "contact",
      "claim": "A parent reports that strangers can message or voice chat with a child unless parental controls are turned on.",
      "stance": "risk",
      "quote": "If you use Roblox Studio, Creator Store, Creator Hub, DevForum, Roblox APIs or other Developer Products, services, or associated software (collectively, “Roblox Creator Platform”), the Creator Terms of Use (“Creator Terms”) also apply to that use."
    },
    {
      "ref": "[D503]",
      "area": "money",
      "claim": "A parent reports that Roblox pushes in-app purchases of Robux and can lead to unauthorized spending by children.",
      "stance": "risk",
      "quote": "You may be asked to provide information like an email address, phone number, or a government-issued photo identification to access certain Content or features in Roblox Player."
    },
    {
      "ref": "[D503]",
      "area": "data",
      "claim": "A parent reports that Roblox collects personal data such as email, phone number, and age, and may share it for advertising.",
      "stance": "risk",
      "quote": "To access the Services, you will need to create a Roblox account (“Account”). Creating an Account enables you to access the Services including Games, Developer Products, Marketplace Items, Assets, User Generated Content, Creator Store assets, content created within Games, images, videos, audio, text (e.g., comments on DevForum, messages), content generated by AI, or other materials, whether provided by Users, Creators, or Roblox (collectively, “Content”)."
    },
    {
      "ref": "[D503]",
      "area": "content",
      "claim": "A parent reports that children can encounter inappropriate user-generated content unless moderation settings are enabled.",
      "stance": "mitigation",
      "quote": "The Content Moderation on Roblox page and the Community Standards explain how you can report Content that is illegal or violates the Roblox Terms including the Community Standards."
    },
    {
      "ref": "[D503]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has faced regulatory fines for mishandling children's data in the EU.",
      "stance": "risk",
      "quote": "If you are a rights holder and want to report UGC that infringes your intellectual property rights (such as copyright or trademark), refer to Section 10.2."
    }
  ]
}
